script:
// Kalickás forgórész forgó mágneses mezőben – 3D nézet (p = 1)
// Squirrel-cage rotor in a rotating magnetic field – 3D view (p = 1)
// A rudakban csak akkor indukálódik áram, ha a mező gyorsabban forog, mint a forgórész (s > 0).
// Current is induced in the bars only while the field turns faster than the rotor (s > 0).
// 3D tengelyek: x a forgástengely, y felfelé / 3D axes: x along the shaft, y up

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Kalickás forgórész forgó mezőben", en: "Cage rotor in a rotating field"});
// Kezdő lassítás (a Sebesség csúszkán állítható) / Initial slow motion (change it on the Speed slider)
timeScale(0.002);
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(0.06);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("f",     {hu: "Frekvencia f", en: "Frequency f"}, 1, 60, 50, 1, "Hz");
param("s",     {hu: "Szlip s", en: "Slip s"}, 0, 1, 0.25, 0.01, "");
param("yaw",   {hu: "Nézet: elforgatás", en: "View: turn"}, -90, 90, -28, 1, "°");
param("pitch", {hu: "Nézet: dőlés", en: "View: tilt"}, -30, 70, 16, 1, "°");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("coils", {hu: "Állórész-tekercsek", en: "Stator coils"}, true);
toggle("field", {hu: "Mágneses erővonalak", en: "Magnetic field lines"}, true);
param("x2",    {hu: "Forgórész X₂ / R₂ (álló forgórésznél)", en: "Rotor X₂ / R₂ (at standstill)"}, 0, 5, 1.5, 0.1, "");
// Legördülő lista: [érték, felirat] párok / Drop-down list: [value, label] pairs
choice("bars", {hu: "Nyilak a rudakon", en: "Arrows on the bars"},
  [["both", {hu: "feszültség és áram", en: "voltage and current"}], ["i", {hu: "csak áram", en: "current only"}],
   ["e", {hu: "csak feszültség", en: "voltage only"}], ["off", {hu: "nincs", en: "none"}]], "both");

const PH = [C.L1, C.L2, C.L3];          // klasszikus színek / classic colours: [C.red, C.yellow, C.blue]
const AXES = [0, deg(120), deg(240)];   // tekercstengelyek / coil axes
const NB = 14, R0 = 1.0, L = 1.7, LC = 2.0, RC = 1.35;
let th = 0, thr = 0, fieldPos = 0;          // ωt, a forgórész szöge, az erővonal-nyilak eltolása / ωt, rotor angle, field-arrow offset
const coilPos = [0, 0, 0];                  // a tekercsáram-nyilak eltolása / coil-current arrow offsets

// A mező iránya a keresztmetszetben (villamos szög) / field direction in the cross-section (electrical angle)
const fieldAngle = () => fieldVec(phases(1, th), AXES).angle;

// Egy rúd feszültsége és árama, −1 … 1 (+ = a tengely mentén +x)
// Voltage and current of one bar, −1 … 1 (+ = along +x)
//   e ∝ s·cos(β − φ)             a mező s-sel arányos sebességgel halad el a rúd mellett / the field passes the bar at a speed ∝ s
//   i = e / Z₂,  Z₂ = R₂ + j·s·X₂  → az áram φ₂ = arc tg(s·X₂/R₂) szöggel késik / the current lags by φ₂
function barValues(j) {
  const rel = thr + j * 2 * PI / NB - fieldAngle();
  const phi2 = atan(P.s * P.x2);
  const iAmp = P.s * sqrt(1 + P.x2 ** 2) / sqrt(1 + (P.s * P.x2) ** 2);   // s = 1-nél 1 / equals 1 at s = 1
  return {e: P.s * cos(rel), i: iAmp * cos(rel + phi2)};
}

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => {
  const w = 2 * PI * P.f, v = 2.2 * P.f;   // a mozgó nyilak sebessége periódusonként / moving-arrow speed per period
  th += w * dt;                           // a mező (hálózat) szöge / field (supply) angle
  thr += w * (1 - P.s) * dt;              // a forgórész s szliptel lassabban forog / the rotor turns slower by the slip s
  const i = phases(1, th);                // a három fázisáram / the three phase currents
  for (let k = 0; k < 3; k++) coilPos[k] += v * i[k] * dt;
  fieldPos += 0.8 * v * dt;
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  // 3D nézet: középpont, lépték (px/egység), elforgatás, dőlés / 3D view: centre, scale (px per unit), turn, tilt
  view3d({x: 500, y: 320, scale: 105, yaw: deg(P.yaw), pitch: deg(P.pitch), dist: 14});
  const phi = fieldAngle(), i = phases(1, th);
  const d = [cos(phi), sin(phi)], e = [-sin(phi), cos(phi)];   // a mező iránya a keresztmetszetben / field direction in the cross-section
  // Innentől a 3D elemek mélység szerint rendeződnek / From here, 3D items are depth-sorted
  begin3();

  // Tengely, rövidrezáró gyűrűk és rudak / shaft, end rings and bars
  wire3([[-L - 1.5, 0, 0], [L + 1.2, 0, 0]], {color: "#a7afba", lw: 18});
  wire3(circle3([-L, 0, 0], "x", R0), {color: "#a7afba", lw: 9}, true);
  wire3(circle3([L, 0, 0], "x", R0), {color: "#a7afba", lw: 9}, true);
  for (let j = 0; j < NB; j++) {
    const b = thr + j * 2 * PI / NB, y = R0 * cos(b), z = R0 * sin(b);
    wire3([[-L, y, z], [L, y, z]], {color: "#b9c0ca", lw: 5});            // a rúd / the bar
    // A nyíl hossza az értékkel arányos, iránya az előjellel / arrow length follows the value, direction its sign
    const v = barValues(j), A = 1.45;                                        // A: a nyíl fél hossza ±1-nél / half length at ±1
    if ((P.bars === "both" || P.bars === "i") && abs(v.i) > 0.03)
      arrow3([-A * v.i, y, z], [A * v.i, y, z], {stroke: C.blue, lw: 4, id: "rúdáram i"});
    if ((P.bars === "both" || P.bars === "e") && abs(v.e) > 0.03)
      arrow3([-A * v.e, 1.14 * y, 1.14 * z], [A * v.e, 1.14 * y, 1.14 * z], {stroke: C.purple, lw: 2.5, id: "rúdfeszültség e"});
  }

  // Erővonalak két keresztmetszetben: a forgórészen át +d irányban / field lines in two slices: across the rotor along +d
  if (P.field) {
    for (const x of [-0.85, 0.85]) for (const sg of [1, -1]) for (const [ae, ad] of [[0.72, 1.6], [0.38, 1.28]]) {
      const loop = [];
      for (let k = 0; k < 60; k++) {
        const u = k / 60 * 2 * PI, ds = ad * sin(u), es = sg * (0.75 - ae * cos(u));
        loop.push([x, d[0] * ds + e[0] * es, d[1] * ds + e[1] * es]);
      }
      path3(loop, {stroke: "#c8963e", lw: 1.6, alpha: 0.85}, true);
      flow3(loop, {pos: fieldPos, dir: 1, spacing: 1.3, size: 10, color: "#e0663a", id: "erővonal"}, true);
    }
    text3("N", [-L - 0.4, -1.9 * d[0], -1.9 * d[1]], {size: 24, bold: true, color: C.N, align: "center"});
    text3("S", [-L - 0.4, 1.9 * d[0], 1.9 * d[1]], {size: 24, bold: true, color: C.S, align: "center"});
  }
  text({hu: "kék: rúdáram i   ·   lila: indukált feszültség e   (a nyíl hossza ∝ érték)",
        en: "blue: bar current i   ·   purple: induced voltage e   (arrow length ∝ value)"}, 22, 64, {size: 13, color: C.gray});

  // Állórész-tekercsek (nyereg alakú): menőoldal az α + 90°-nál / stator coils (saddle): go side at α + 90°
  if (P.coils) for (let k = 0; k < 3; k++) {
    const a1 = AXES[k] + PI / 2, a2 = AXES[k] - PI / 2, rc = RC + k * 0.07, pts = [];
    const at = (x, a) => [x, rc * cos(a), rc * sin(a)];
    pts.push(at(-LC, a1), at(LC, a1));
    for (let q = 1; q < 24; q++) pts.push(at(LC, a1 - q / 24 * PI));
    pts.push(at(LC, a2), at(-LC, a2));
    for (let q = 1; q < 24; q++) pts.push(at(-LC, a2 + q / 24 * PI));
    wire3(pts, {color: PH[k], lw: 7}, true);
    if (abs(i[k]) > 0.08) flow3(pts, {pos: coilPos[k], dir: sign(i[k]), spacing: 1.4, size: 12, color: "#1e9bd7", alpha: min(1, abs(i[k]) * 1.4), id: "tekercsáram"}, true);
    text3("L" + (k + 1), at(LC + 0.45, AXES[k]), {size: 15, bold: true, color: PH[k], align: "center"});
  }
  // A 3D elemek kirajzolása (a távoliak előbb) / Draw the 3D items (far ones first)
  end3();

  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Szinkron fordulatszám nₛ = 60·f", en: "Synchronous speed nₛ = 60·f"}, 60 * P.f, "1/min");
  show({hu: "Forgórész n = (1 − s)·nₛ", en: "Rotor speed n = (1 − s)·nₛ"}, (1 - P.s) * 60 * P.f, "1/min");
  show({hu: "Rúdáram frekvenciája f₂ = s·f", en: "Bar current frequency f₂ = s·f"}, P.s * P.f, "Hz");
  show({hu: "Az áram késése φ₂ = arc tg(s·X₂/R₂)", en: "Current lag φ₂ = atan(s·X₂/R₂)"}, todeg(atan(P.s * P.x2)), "°");
  val({s: P.s, f2: P.s * P.f, phi2: todeg(atan(P.s * P.x2)), n: (1 - P.s) * 60 * P.f});   // a Jelölők fülnek / for the Markup tab
  show({hu: "Állapot", en: "State"}, tr(P.s > 0 ? {hu: "a mező elhalad a rudak mellett → áram, nyomaték", en: "the field slips past the bars → current, torque"}
                                                 : {hu: "n = nₛ: nincs indukált áram, nincs nyomaték", en: "n = nₛ: no induced current, no torque"}), "");
  for (let k = 0; k < 3; k++) plot("i" + "₁₂₃"[k], i[k], {color: PH[k], group: "i"});
});
